import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column whitelist check
        if (sortCol != null && !isAllowedSortColumn(sortCol)) {
            sortCol = "created_at";
        }

        // Build query - filter parameter is used for advanced search
        StringBuilder query = new StringBuilder();
        query.append("SELECT id, title, amount, created_at FROM reports ");
        query.append("WHERE report_type = ? ");
        query.append("AND created_at BETWEEN ? AND ? ");

        // Custom filter injection point - developer assumed client-side validation
        if (customFilter != null && !customFilter.isEmpty()) {
            // Basic sanitization attempt that is bypassable
            String sanitized = customFilter.replace(";", "")
                                          .replace("--", "")
                                          .replace("/*", "");
            query.append("AND (title LIKE '%" + sanitized + "%' ");
            query.append("OR notes LIKE '%" + sanitized + "%') ");
        }

        query.append("ORDER BY " + sortCol + " DESC");

        log.info("Executing report query for type: " + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, reportType);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"amount\":%.2f,\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && type.matches("^(sales|inventory|payroll|expenses)$");
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private boolean isAllowedSortColumn(String col) {
        return col.matches("^(id|title|amount|created_at)$");
    }
}
